CREATE TABLE public.password_security_baselines (user_id uuid PRIMARY KEY, baseline_digest bytea NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.password_security_baselines TO service_role;
ALTER TABLE public.password_security_baselines ENABLE ROW LEVEL SECURITY;
INSERT INTO public.password_security_baselines(user_id, baseline_digest) SELECT id, sha256(convert_to(encrypted_password,'UTF8')) FROM auth.users WHERE email LIKE 'cpf%@cooperado.coopaiba.com.br' AND encrypted_password IS NOT NULL;
CREATE FUNCTION public.password_change_required_for(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.password_security_baselines b JOIN auth.users u ON u.id=b.user_id WHERE b.user_id=_user_id AND b.baseline_digest=sha256(convert_to(u.encrypted_password,'UTF8'))) $$;
REVOKE ALL ON FUNCTION public.password_change_required_for(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.password_change_required_for(uuid) TO service_role;
CREATE FUNCTION public.needs_password_change() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT public.password_change_required_for(auth.uid()) $$;
REVOKE ALL ON FUNCTION public.needs_password_change() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.needs_password_change() TO authenticated, service_role;
CREATE FUNCTION public.capture_initial_password() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.password_security_baselines(user_id,baseline_digest) SELECT id,sha256(convert_to(encrypted_password,'UTF8')) FROM auth.users WHERE id=NEW.user_id AND email LIKE 'cpf%@cooperado.coopaiba.com.br' AND encrypted_password IS NOT NULL ON CONFLICT (user_id) DO NOTHING; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.capture_initial_password() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER capture_initial_password AFTER INSERT ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.capture_initial_password();
CREATE FUNCTION public.capture_password_reset(_user_id uuid) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$ INSERT INTO public.password_security_baselines(user_id,baseline_digest) SELECT id,sha256(convert_to(encrypted_password,'UTF8')) FROM auth.users WHERE id=_user_id AND encrypted_password IS NOT NULL ON CONFLICT(user_id) DO UPDATE SET baseline_digest=EXCLUDED.baseline_digest,created_at=now() $$;
REVOKE ALL ON FUNCTION public.capture_password_reset(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.capture_password_reset(uuid) TO service_role;
DO $$ DECLARE t record; BEGIN FOR t IN SELECT tablename FROM pg_tables WHERE schemaname='public' AND tablename <> 'password_security_baselines' LOOP EXECUTE format('CREATE POLICY password_rotation_required ON public.%I AS RESTRICTIVE FOR ALL TO authenticated USING (NOT public.needs_password_change()) WITH CHECK (NOT public.needs_password_change())', t.tablename); END LOOP; END $$;
CREATE POLICY password_rotation_required ON storage.objects AS RESTRICTIVE FOR ALL TO authenticated USING (NOT public.needs_password_change()) WITH CHECK (NOT public.needs_password_change());
CREATE FUNCTION public.enforce_password_rotation() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF auth.role()='authenticated' AND current_setting('request.path', true) IS DISTINCT FROM '/rpc/needs_password_change' AND public.needs_password_change() THEN RAISE SQLSTATE '42501' USING MESSAGE='Troque sua senha inicial para continuar.'; END IF; END $$;
REVOKE ALL ON FUNCTION public.enforce_password_rotation() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.enforce_password_rotation() TO authenticated, service_role;
ALTER ROLE authenticator SET pgrst.db_pre_request='public.enforce_password_rotation';
NOTIFY pgrst, 'reload config';